// AG Studio inside an Appsmith custom widget.
// The UMD bundle (~5MB) exposes window.agStudio and carries its own copies of
// ag-grid-enterprise and ag-charts-enterprise, so nothing else is loaded here.
var api = null;
var appliedKey = '';
var licenceNote = 'no licence key set — running unlicensed (watermarked)';
var liveState = null;
var lastModel = null;
var lastDataSig = '';
var lastStateKey = -1;
var lastMode = '';
var lastSaveRequest = -1;

function el(id) { return document.getElementById(id); }

function setStatus(text, kind) {
  var n = el('studio-status');
  if (!n) return;
  n.className = 'status ' + (kind || '');
  n.textContent = text;
}

function rowsOf(model) {
  return (model && Array.isArray(model.rows)) ? model.rows : [];
}

function modeOf(model) {
  return (model && model.mode === 'view') ? 'view' : 'edit';
}

// Cheap signature so we only rebuild Studio when the dataset actually changes.
function dataSignature(model) {
  var rows = rowsOf(model);
  return [model && model.customerId, rows.length, rows.length ? Object.keys(rows[0]).join(',') : ''].join('|');
}

// --- licence ---------------------------------------------------------------
// Studio unlocks every feature without a key and only watermarks, so a key buys
// nothing except the watermark going away. A GRID or CHARTS key is worse than
// no key at all: it moves Studio from "License Key Not Found" (trial, all
// features unlocked) to "Invalid License Key". So a key is applied unless
// Studio tells us outright that it is the wrong type. The empty Set asks about
// STUDIO-CORE, the lowest tier, which any STUDIO-* key satisfies.
function inspectKey(key) {
  try {
    var d = agStudio.AgStudioLicenseManager.getLicenseDetails(key, new Set());
    if (!d) return { apply: true, note: 'licence key applied (no details returned)' };
    if (d.valid && !d.expired) {
      return {
        apply: true,
        note: 'licence OK' + (d.isTrial ? ' (trial)' : '') + (d.expiry ? ', expires ' + d.expiry : '')
      };
    }
    // Every remaining branch is a key Studio would reject, and a rejected key
    // is worse than none: it swaps the trial for an "Invalid License" watermark
    // with nothing unlocked in return. So report what is wrong and stay on the
    // trial rather than hand the key over.
    if (d.incorrectLicenseType) {
      return {
        apply: false,
        note: 'WRONG LICENCE TYPE — this is a ' + (d.suppliedLicenseType || 'non-Studio') +
              ' key and Studio needs ' + (d.currentLicenseType || 'STUDIO-*') +
              '. Ignored, so the trial stays in force.'
      };
    }
    if (d.expired) {
      return {
        apply: false,
        note: 'licence expired' + (d.expiry ? ' on ' + d.expiry : '') +
              ' — ignored, so the trial stays in force.'
      };
    }
    return {
      apply: false,
      note: 'Studio does not recognise this key — check it was pasted whole. ' +
            'Ignored, so the trial stays in force.'
    };
  } catch (e) {
    // getLicenseDetails is marked internal. If it moves, apply the key anyway
    // and let Studio's own console banner say what it made of it.
    return { apply: true, note: 'licence key applied (could not verify)' };
  }
}

// Returns true when the key in force changed, so the caller can rebuild —
// setLicenseKey only takes effect on the next createStudio call.
function applyLicense(model) {
  var key = (model && model.licenseKey ? String(model.licenseKey) : '').trim();
  if (key === appliedKey) return false;
  appliedKey = key;
  if (!key) {
    licenceNote = 'no licence key set — running unlicensed (watermarked)';
    return true;
  }
  if (!window.agStudio || !agStudio.AgStudioLicenseManager) return false;
  var verdict = inspectKey(key);
  licenceNote = verdict.note;
  if (verdict.apply) {
    try {
      agStudio.AgStudioLicenseManager.setLicenseKey(key);
    } catch (e) {
      console.warn('AG Studio setLicenseKey failed', e);
      licenceNote = 'licence key rejected by setLicenseKey — see console';
    }
  }
  return true;
}

// --- export ----------------------------------------------------------------
// Appsmith renders custom widgets in an iframe sandboxed with
//   allow-forms allow-modals allow-orientation-lock allow-pointer-lock
//   allow-popups allow-scripts
// and notably no allow-downloads, so the synthetic <a download> click Studio
// uses to save a CSV, workbook or image is blocked by the browser before it
// reaches the disk. A licence does not change that. Instead the click is caught
// here, the Blob kept, and the bytes handed to Appsmith, whose own download()
// runs in the parent frame where downloads are allowed.
var MAX_EXPORT_BYTES = 8 * 1024 * 1024;
var blobsByUrl = {};

// Charts name their download "image" with no extension, so give the file one
// the operating system will recognise.
var MIME_EXT = {
  'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/svg+xml': 'svg',
  'text/csv': 'csv', 'text/plain': 'txt', 'application/json': 'json',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx'
};

function withExtension(name, type) {
  if (name.indexOf('.') >= 0) return name;
  var ext = MIME_EXT[String(type || '').toLowerCase()];
  return ext ? name + '.' + ext : name;
}

// Chart images never touch createObjectURL — ag-charts hands the anchor a
// base64 data: URL straight from canvas.toDataURL() — so that shape is read
// off the href directly.
function dataUrlPayload(href) {
  if (href.slice(0, 5) !== 'data:') return null;
  var comma = href.indexOf(',');
  if (comma < 0) return null;
  var meta = href.slice(5, comma);
  if (meta.indexOf(';base64') < 0) return null;
  return { type: meta.split(';')[0] || 'application/octet-stream', url: href };
}

function interceptDownloads() {
  if (window.URL && typeof URL.createObjectURL === 'function') {
    var mint = URL.createObjectURL.bind(URL);
    URL.createObjectURL = function (obj) {
      var url = mint(obj);
      if (typeof Blob !== 'undefined' && obj instanceof Blob) {
        blobsByUrl[url] = obj;
        // Studio also mints blob URLs for chart images it never downloads, so
        // let them go again rather than hold every Blob for the life of the page.
        setTimeout(function () { delete blobsByUrl[url]; }, 60000);
      }
      return url;
    };
  }

  // Grid exports dispatch a synthetic click with bubbles: false and chart
  // images call anchor.click(), which does bubble. The capture phase runs from
  // the document down to the target either way, so it catches both.
  document.addEventListener('click', function (ev) {
    var anchor = (ev.target && ev.target.closest) ? ev.target.closest('a[download]') : null;
    if (!anchor) return;
    var href = anchor.getAttribute('href') || '';
    var name = anchor.getAttribute('download') || 'export';

    var blob = blobsByUrl[href];
    if (blob) {
      ev.preventDefault();
      ev.stopPropagation();
      exportBlob(withExtension(name, blob.type), blob);
      return;
    }

    var payload = dataUrlPayload(href);
    if (payload) {
      ev.preventDefault();
      ev.stopPropagation();
      sendExport(withExtension(name, payload.type), payload.type, payload.url);
    }
  }, true);
}

function exportBlob(fileName, blob) {
  // Checked here as well as in sendExport: blob.size is free, whereas finding
  // out after readAsDataURL means holding the whole export in memory twice
  // over just to reject it.
  if (blob.size > MAX_EXPORT_BYTES) { tooBig(blob.size); return; }
  setStatus('Preparing ' + fileName + '…');
  var reader = new FileReader();
  reader.onerror = function () { setStatus('Could not read the export.', 'err'); };
  reader.onload = function () {
    // readAsDataURL gives "data:<type>;base64,<payload>"; Appsmith's download()
    // wants the bare payload, with the type passed alongside it.
    var url = String(reader.result || '');
    if (url.indexOf(',') < 0) { setStatus('Could not encode the export.', 'err'); return; }
    sendExport(fileName, blob.type || 'application/octet-stream', url);
  };
  reader.readAsDataURL(blob);
}

function tooBig(bytes) {
  setStatus('That export is ' + (bytes / 1048576).toFixed(1) + 'MB, over the ' +
            (MAX_EXPORT_BYTES / 1048576) + 'MB this widget can hand to Appsmith. Narrow it and retry.', 'err');
}

// Appsmith's download() has a base64 branch that pulls "data:<type>;base64,..."
// over XHR, and this instance's CSP lists no data: scheme in connect-src, so
// that branch dies with a Network Error before anything is written. Handing it
// the whole data: URL instead lands in its plain branch, where downloadjs
// decodes the payload locally with atob and never touches the network.
function sendExport(fileName, fileType, dataUrl) {
  var bytes = Math.floor((dataUrl.length - dataUrl.indexOf(',') - 1) * 3 / 4);
  if (bytes > MAX_EXPORT_BYTES) { tooBig(bytes); return; }
  try {
    appsmith.triggerEvent('onExportFile', {
      fileName: fileName,
      fileType: fileType,
      fileData: dataUrl
    });
    setStatus('Sent ' + fileName + ' to the browser.', 'ok');
    setTimeout(function () { setStatus(statusLine(lastModel), 'ok'); }, 4000);
  } catch (e) {
    console.error('handing the export to Appsmith failed', e);
    setStatus('Could not hand the export to Appsmith — see console.', 'err');
  }
}

// --- saving ----------------------------------------------------------------
// The report state deliberately does not travel through appsmith.updateModel.
// The widget's `model` is a meta property whose default is `defaultModel`, so
// it is reset to that binding's value whenever any dependency re-evaluates —
// picking a customer, flipping the mode switch — which silently dropped the
// state before Save could read it. The state is kept here instead and pushed
// out as an event only when Save is actually pressed.
function handleSaveRequest(model) {
  var req = Number(model && model.saveRequest) || 0;
  if (req === lastSaveRequest) return;
  lastSaveRequest = req;
  var state = liveState;
  if (!state && api && typeof api.getState === 'function') {
    try { state = api.getState(); } catch (e) { state = null; }
  }
  if (!state) {
    setStatus('Nothing to save yet — add a widget first.', 'warn');
    return;
  }
  try {
    appsmith.triggerEvent('onViewSaved', { view: state });
    setStatus('View saved.', 'ok');
    setTimeout(function () { setStatus(statusLine(lastModel), 'ok'); }, 3000);
  } catch (e) {
    console.error('saving the view failed', e);
    setStatus('Could not save the view — see console.', 'err');
  }
}

// Dark theme built off studioTheme, matching the palette the Analytics page
// already uses for its ECharts widgets (#0F172A / #1E293B / #334155 / #E2E8F0).
