function darkTheme() {
  try {
    return agStudio.studioTheme.withParams(DARK);
  } catch (e) {
    console.warn('dark theme failed, falling back to default', e);
    return undefined;
  }
}

function statusLine(model) {
  var n = rowsOf(model).length.toLocaleString();
  var mode = modeOf(model) === 'view' ? 'view mode (read only)' : 'edit mode';
  return n + ' rows · ' + mode + ' · ' + licenceNote;
}

function buildStudio(model) {
  var root = el('studio-root');
  if (!root) return;
  var rows = rowsOf(model);

  if (api && typeof api.destroy === 'function') {
    try { api.destroy(); } catch (e) { /* already gone */ }
  }
  api = null;
  liveState = null;
  root.innerHTML = '';

  if (rows.length === 0) {
    setStatus('No rows returned for this customer.', 'warn');
    return;
  }

  var props = {
    mode: modeOf(model),
    theme: darkTheme(),
    // Fields are inferred from the row data when not supplied.
    data: {
      sources: [{
        id: 'monthly_usage',
        name: (model && model.customerName ? model.customerName + ' — ' : '') + 'Monthly Usage',
        description: 'Monthly billed usage and charges per location, utility and vendor.',
        data: rows
      }]
    },
    dataOptions: { maxExportRows: -1 },
    onStudioReady: function () {
      setStatus(statusLine(model), 'ok');
    },
    onErrorRaised: function (ev) {
      console.error('AG Studio error', ev);
      setStatus('Studio error: ' + ((ev && ev.message) || 'see console'), 'err');
    },
    // Held locally only — see handleSaveRequest for why this never goes into
    // the widget model.
    onStateUpdated: function (ev) {
      if (ev && ev.state) {
        liveState = ev.state;
      } else if (api && typeof api.getState === 'function') {
        try { liveState = api.getState(); } catch (e) { /* leave the last good state */ }
      }
    }
  };

  if (model && model.savedState) props.initialState = model.savedState;

  try {
    api = agStudio.createStudio(root, props);
    setStatus('Starting AG Studio…');
  } catch (e) {
    console.error(e);
    setStatus('createStudio failed: ' + (e && e.message), 'err');
  }
}

function render(model) {
  if (!window.agStudio || !agStudio.createStudio) {
    setStatus('AG Studio bundle did not load — check the CDN script tag.', 'err');
    return;
  }
  lastModel = model;

  // A key only reaches Studio through createStudio, so a new one forces a rebuild.
  var keyChanged = applyLicense(model);

  if (lastSaveRequest < 0) {
    // First model of the session. agStudioSaveRequest is a store value and
    // survives reloads, so adopt what is there rather than read it as a Save.
    lastSaveRequest = Number(model && model.saveRequest) || 0;
  } else {
    handleSaveRequest(model);
  }

  var sig = dataSignature(model);
  var stateKey = Number(model && model.stateKey) || 0;
  var mode = modeOf(model);

  // stateKey only moves when a saved view is deliberately loaded or reset.
  // Saving does not touch it, so a save no longer tears down the workspace.
  if (sig === lastDataSig && stateKey === lastStateKey && !keyChanged) {
    if (api && mode !== lastMode) {
      lastMode = mode;
      try {
        api.setProperty('mode', mode);
        setStatus(statusLine(model), 'ok');
      } catch (e) {
        console.warn('mode switch failed, rebuilding', e);
        buildStudio(model);
      }
    }
    return;
  }

  lastDataSig = sig;
  lastStateKey = stateKey;
  lastMode = mode;
  buildStudio(model);
}

// The bundle is large; poll briefly for the global before first render.
function whenReady(model, tries) {
  if (window.agStudio && agStudio.createStudio) { render(model); return; }
  if (tries <= 0) {
    setStatus('Timed out waiting for the AG Studio bundle (~5MB). Reload the page.', 'err');
    return;
  }
  setStatus('Loading AG Studio bundle…');
  setTimeout(function () { whenReady(model, tries - 1); }, 250);
}

interceptDownloads();

appsmith.onReady(function () {
  whenReady(appsmith.model, 160);

  appsmith.onModelChange(function (model) {
    if (window.agStudio && agStudio.createStudio) render(model);
  });
});
